use super::*;
use semio_s_artifact_layout_layout_model::Frame as LayoutFrame;
use semio_framework_value::{RetireOwned,DslValue,Number,retained_clone::RetainedCloneSource};
use semio_framework_value_dictionary::{QuestionDictionary,QuestionDictionaryEntry};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn source<T:RetireOwned+Send+Sync+'static>(v:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let g=grant(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()});RetainedCloneSource::admit_owned(v,(),g).unwrap_or_else(|(e,_,_)|panic!("{e}")).0}
fn close_source<T:RetireOwned+Send+Sync+'static>(s:&mut RetainedCloneSource<T>){while !s.terminal_is_empty(){let d=s.next_close_demand(256).unwrap();s.close_step(grant(d)).unwrap();}}
fn observe(g:RetainedCloneGrant,f:impl FnOnce()->RetainedCloneStep)->RetainedCloneStep{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);assert!(step.progress().fits(g));step}
fn set_value(document:&mut LayoutSnapshot,value:DslValue){document.data_fields=Some(QuestionDictionary{entries:vec![QuestionDictionaryEntry{question_id:"original".into(),value}]})}
fn intrinsic_pair(kind:&str)->(DslValue,DslValue){match kind{"bytes-array"=>(DslValue::Bytes(vec![1,2]),DslValue::Array(vec![DslValue::Number(Number::UInt(1)),DslValue::Number(Number::UInt(2))])),"unsigned-signed"=>(DslValue::Number(Number::UInt(1)),DslValue::Number(Number::Int(1))),"null-object"=>(DslValue::Null,DslValue::Object(Vec::new())),"text-bytes"=>(DslValue::String("abc".into()),DslValue::Bytes(vec![97,98,99])),"float-word"=>(DslValue::Number(Number::Float(0.0)),DslValue::Number(Number::Float(-0.0))),_=>{let a=vec![("a".into(),DslValue::Null),("b".into(),DslValue::Bool(true))];let mut b=a.clone();b.reverse();(DslValue::Object(a),DslValue::Object(b))}}}
#[test]
fn original_snapshot_words_and_deep_dictionary_loans_have_exact_native_growth_and_close_receipts(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let common:serde_json::Value=serde_json::from_str(include_str!("../../../🎚️simple/🧪️tests/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let mut left=decode::<LayoutSnapshot>(&common["base"]);let mut right=decode::<LayoutSnapshot>(&common["base"]);if let Some(name)=row["leftName"].as_str(){left.name=name.into()}if let Some(name)=row["rightName"].as_str(){right.name=name.into()}if let Some(bits)=row["left64"].as_str(){left.grid.baseline_offset=f64::from_bits(u64::from_str_radix(bits,16).unwrap())}if let Some(bits)=row["right64"].as_str(){right.grid.baseline_offset=f64::from_bits(u64::from_str_radix(bits,16).unwrap())}if let(Some(a),Some(b))=(row["left32"].as_str(),row["right32"].as_str()){let LayoutFrame::Rect{fill,..}=&mut left.pages[0].frames[0]else{panic!()};*fill=Some([f32::from_bits(u32::from_str_radix(a,16).unwrap()),0.0,0.0,1.0]);let LayoutFrame::Rect{fill,..}=&mut right.pages[0].frames[0]else{panic!()};*fill=Some([f32::from_bits(u32::from_str_radix(b,16).unwrap()),0.0,0.0,1.0])}if row["reverseFrames"]==true{right.pages[0].frames.reverse()}if row["changeFrameX"]==true{let bounds=match &mut right.pages[0].frames[0]{LayoutFrame::Rect{bounds,..}|LayoutFrame::Image{bounds,..}|LayoutFrame::Text{bounds,..}=>bounds};bounds.x=99.0}if row["changeVisible"]==true{let visible=match &mut right.pages[0].frames[0]{LayoutFrame::Rect{visible,..}|LayoutFrame::Image{visible,..}|LayoutFrame::Text{visible,..}=>visible};*visible=Some(false)}if let Some(depth)=row["dictionaryDepth"].as_u64(){let mut a=DslValue::Number(Number::UInt(1));let mut b=DslValue::Number(Number::UInt(row["rightLeaf"].as_u64().unwrap_or(1)));for _ in 0..depth{a=DslValue::Array(vec![a]);b=DslValue::Array(vec![b])}set_value(&mut left,a);set_value(&mut right,b)}if let Some(kind)=row["intrinsicPair"].as_str(){let(a,b)=intrinsic_pair(kind);set_value(&mut left,a);set_value(&mut right,b)}let expected=row["equal"].as_bool().unwrap();assert_eq!(left==right,expected,"{}: independent native typed PartialEq",row["name"]);for cut in std::iter::once(usize::MAX).chain(fixture["cuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize)){let mut l=source(left.clone());let mut r=source(right.clone());let mut owner=LayoutDocumentEquality::default();for turn in 0..cut{if owner.result().is_some(){break}assert!(turn<1000000);let d=owner.demand(l.borrow(),r.borrow()).unwrap();let g=grant(d);assert_eq!(observe(Default::default(),||owner.advance(l.borrow(),r.borrow(),Default::default()).unwrap()).progress(),Default::default());for short in[RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g}]{if short!=g{assert_eq!(observe(short,||owner.advance(l.borrow(),r.borrow(),short).unwrap()).progress(),Default::default())}}observe(g,||owner.advance(l.borrow(),r.borrow(),g).unwrap());}if cut==usize::MAX{assert_eq!(owner.result(),Some(expected));let mut foreign=source(left.clone());assert!(owner.demand(foreign.borrow(),r.borrow()).is_err());close_source(&mut foreign)}owner.begin_close();for turn in 0..1000000{if owner.terminal_is_empty(){break}assert!(turn<999999);let d=owner.close_demand(256).unwrap();assert_eq!(observe(Default::default(),||owner.close_step(Default::default()).unwrap()).progress(),Default::default());observe(grant(d),||owner.close_step(grant(d)).unwrap());}assert_eq!(l.borrow().get(),&left);assert_eq!(r.borrow().get(),&right);close_source(&mut l);close_source(&mut r)}}}
